# find pairwise relations: equal, reversed
def rev(r): return r[::-1]
for i in range(30):
    for j in range(30):
        if i!=j and rows[i]==rows[j]: print('eq',i,j)
        if i<j and rows[i]==rev(rows[j]): print('rev',i,j)
# also check columns reversed relations
cols=[list(c) for c in zip(*rows)]
for i in range(30):
    for j in range(30):
        if i<j and cols[i]==cols[j]: print('ceq',i,j)
        if cols[i]==rev(cols[j]): print('crev',i,j)

